CREATE TABLE `customer_billing_invoices` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`invoice_number` text NOT NULL,`quote_version_id` integer NOT NULL,`customer_id` integer NOT NULL,`property_id` integer NOT NULL,`version` integer DEFAULT 1 NOT NULL,`currency` text NOT NULL,`total` real NOT NULL,`deposit_required` real DEFAULT 0 NOT NULL,`due_date` text NOT NULL,`status` text DEFAULT 'issued' NOT NULL,`customer_snapshot_json` text NOT NULL,`document_sha256` text NOT NULL,`created_by` integer NOT NULL,`issued_at` text NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `customer_billing_invoices_invoice_number_unique` ON `customer_billing_invoices` (`invoice_number`); CREATE INDEX `customer_billing_invoices_property_idx` ON `customer_billing_invoices` (`property_id`); CREATE INDEX `customer_billing_invoices_quote_idx` ON `customer_billing_invoices` (`quote_version_id`);
CREATE TABLE `customer_billing_transactions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`invoice_id` integer NOT NULL,`transaction_type` text NOT NULL,`status` text NOT NULL,`amount` real NOT NULL,`currency` text NOT NULL,`provider` text NOT NULL,`provider_session_id` text,`provider_transaction_id` text,`provider_event_id` text,`idempotency_key` text NOT NULL,`receipt_number` text,`occurred_at` text NOT NULL,`metadata_json` text DEFAULT '{}' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `customer_billing_transactions_provider_session_id_unique` ON `customer_billing_transactions` (`provider_session_id`); CREATE UNIQUE INDEX `customer_billing_transactions_provider_event_id_unique` ON `customer_billing_transactions` (`provider_event_id`); CREATE UNIQUE INDEX `customer_billing_transactions_idempotency_key_unique` ON `customer_billing_transactions` (`idempotency_key`); CREATE UNIQUE INDEX `customer_billing_transactions_receipt_number_unique` ON `customer_billing_transactions` (`receipt_number`); CREATE INDEX `customer_billing_transactions_invoice_idx` ON `customer_billing_transactions` (`invoice_id`);
